  out=$(./jq -n "1 as \$$kw | \$$kw" 2>&1) || { echo "FAIL as/ref $kw: $out"; fail=1; }
  [ "$out" = 1 ] || { echo "BAD as/ref $kw: $out"; fail=1; }
