  [ "$out" = 2 ] || { echo "BAD param $kw: $out"; fail=1; }
  out=$(./jq -c -n "1 as \$$kw | {\$$kw}" 2>&1) || { echo "FAIL dict $kw: $out"; fail=1; }
  [ "$out" = "{\"$kw\":1}" ] || { echo "BAD dict $kw: $out"; fail=1; }
  out=$(./jq -c -n "[1] as [\$$kw] | \$$kw" 2>&1) || { echo "FAIL arraypat $kw: $out"; fail=1; }
  [ "$out" = 1 ] || { echo "BAD arraypat $kw: $out"; fail=1; }
  out=$(./jq -c -n "{\"$kw\":1} as {\$$kw} | \$$kw" 2>&1) || { echo "FAIL objpat $kw: $out"; fail=1; }
  [ "$out" = 1 ] || { echo "BAD objpat $kw: $out"; fail=1; }
  out=$(./jq -c -n "[label \$$kw | 1, break \$$kw]" 2>&1) || { echo "FAIL label/break $kw: $out"; fail=1; }
  [ "$out" = "[1]" ] || { echo "BAD label/break $kw: $out"; fail=1; }
done
echo "fail=$fail"
'

